self.KB_CONTENT["card:784476"]={"id":"card:784476","ty":"card","sourceId":"784476","title":"『資產出售建立作業』中的『統一編號 (TC050)』為何？","ver":"GP4以上","topic":"資產","keywords":["資產","發票","編號","號碼"],"y":"other","answer":"* 共用參數設定之功能別設為「1.台灣版」，發票號碼依總公司控管，可點選[F2]統一編號資料查詢。* 輸入時，長度只可輸入8碼。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
