self.KB_CONTENT["card:778422"]={"id":"card:778422","ty":"card","sourceId":"778422","title":"『製令需求檢視表』中的『選擇製令入庫庫別』為何？","ver":"GP4以上","topic":"檢視表","keywords":["檢視表","製令","入庫","庫別"],"y":"other","answer":"* 可以製令單頭入庫庫別為選項條件，空白表全部資料。可按[F2]查詢庫別資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
