self.KB_CONTENT["card:792606"]={"id":"card:792606","ty":"card","sourceId":"792606","title":"『出貨通知單建立作業』中的『商品描述 (TB008)』為何？","ver":"GP4以上","topic":"單身","keywords":["單身","開窗","出貨","商品"],"y":"other","answer":"* 開窗供維護。* 可輸入單身商品的商品描述。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
