self.KB_CONTENT["field:757784"]={"id":"field:757784","ty":"field","sourceId":"757784","title":"當條件給的越多，可以查到越精確的資料；但是若有一個條件不相符，則會無法帶出要查詢的資料。","ver":"iGP","topic":"","keywords":[],"job":"請購單明細表","code":"","answer":"進階選項","file":"fields.jsonl"};
